void update() {
    vec3 center;
    for (int i = 0; i < 8; ++i) {
        int led_idx = i * 4;
        vec3 color = shade(led(led_idx));
        center += vec3(color.x, color.y, color.z);
    }
}
vec3 shade(Led led) {
    float phase = fract(led.s - time * speed);
    float band = smoothstep(width, 0.0, abs(phase - 0.5));
    return tint * band;
}}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    vec3 color = vec3(1.0, 0.0, 0.0);
    for (int i = 0; i < 24; i++) {
        float phase = fract(led.s - time * speed * 2);
        float brightness = smoothstep(0.5, 0.0, abs(phase - 0.5));
        color *= vec3(brightness / 1.0, brightness / 1.0, brightness / 1.0);
    }
    trail[led.idx] += color;
}
vec3 shade(Led led) {
    return color;
}

uniform float speed : 0.0 .. 5.0 = 1.0;
