        vec4 color = sample(seg_node(i, 0), led.uv);
        trail[led.idx] += color;
        paint(img, led.uv, color);
    }
}
vec3 shade(Led led) {
    float phase = fract(led.s - time * speed);
    float band = smoothstep(width, 0.0, abs(phase - 0.5));
    return tint * band;
}}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    vec3 trail[led.count];
    for (int i = 0; i < led.count; ++i) {
        trail[i] = mix(vec3(0.0, 0.0, 0.0), vec3(1.0, 1.0, 1.0), fract(led.s - time * speed));
    }
}
vec3 shade(Led led) {
    float phase = fract(led.s - time * speed);
    float band = smoothstep(width, 0.0, abs(phase - 0.5));
    return tint * band;
}}

